mapper.select:
SELECT a.id, a.student_id, a.type, a.head, a.content, a.updated_date_time, s.name, f.file_url AS avatar FROM article a LEFT JOIN it_student s ON s.student_id = a.student_id AND s.deleted = 0 LEFT JOIN student_file f ON f.id = s.avatar_id AND f.deleted = 0
WHERE a.type = #{type}
ORDER BY a.updated_date_time DESC, a.id DESC LIMIT #{offset}, #{size}

SELECT *
FROM article
WHERE article.student_id = #{studentId}
ORDER BY article.updated_date_time DESC, article.id DESC
LIMIT #{offset},#{size}

SELECT COUNT(*)
FROM article
WHERE updated_date_time > #{updatedDateTime}

SELECT COUNT(*)
FROM article
WHERE article.student_id = #{studentId}
